<span class="line"><span style="color:#50A14F;">    &quot;gh-pages&quot;</span><span style="color:#0184BC;">:</span><span style="color:#50A14F;"> &quot;gh-pages -d build -t true&quot;</span><span style="color:#383A42;">, </span><span style="color:#A0A1A7;font-style:italic;">// Новый</span></span>
